sources.SelectionBridge.ets:
export class SelectionBridge {
 currentId: string = ''
 onItemSelected(entry: Entry): void {
  this.currentId = entry.id
  this.openEditor()
 }
 openEditor(): void {}
}

sources.SelectionHint.ets:
export class SelectionHint {
 selected: boolean = false
 onClick(): void {
  this.selected = !this.selected
 }
}

